WITH drug1_source AS (
 SELECT concept_id FROM omop.concept WHERE vocabulary_id='RxNorm' AND concept_code='451473' AND invalid_reason IS NULL
),
drug1_mapped AS (
 SELECT concept_id_2 AS concept_id FROM drug1_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id='Maps to'
),
drug1_hierarchy AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug1_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug2_source AS (
 SELECT concept_id FROM omop.concept WHERE vocabulary_id='RxNorm' AND concept_code='1658259' AND invalid_reason IS NULL
),
drug2_mapped AS (
 SELECT concept_id_2 AS concept_id FROM drug2_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id='Maps to'
),
drug2_hierarchy AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug2_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
)
SELECT COUNT(DISTINCT de1.person_id) AS patient_count
FROM omop.drug_exposure de1
JOIN omop.drug_exposure de2 ON de1.person_id = de2.person_id
WHERE de1.drug_concept_id IN (SELECT concept_id FROM drug1_hierarchy)
  AND de2.drug_concept_id IN (SELECT concept_id FROM drug2_hierarchy)
  AND CAST(
    EXTRACT(epoch FROM
      CAST(GREATEST(de1.drug_exposure_start_date, de2.drug_exposure_start_date) AS TIMESTAMP) -
      CAST(LEAST(de1.drug_exposure_start_date, de2.drug_exposure_start_date) AS TIMESTAMP)
    ) / 86400 AS BIGINT
  ) <= 30;

WITH condition1_source AS (
 SELECT concept_id FROM omop.concept WHERE vocabulary_id='SNOMED' AND concept_code='68566005' AND invalid_reason IS NULL
),
condition1_mapped AS (
 SELECT concept_id_2 AS concept_id FROM condition1_source cs JOIN omop.concept_relationship cr ON cs.concept_id = cr.concept_id_1 WHERE cr.relationship_id='Maps to'
),
condition1_concepts AS (
 SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM condition1_mapped cm JOIN omop.concept c ON cm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
)
SELECT COUNT(DISTINCT co.person_id) FROM omop.condition_occurrence co JOIN omop.person p ON co.person_id = p.person_id WHERE co.condition_concept_id IN (SELECT concept_id FROM condition1_concepts) AND p.race_concept_id IS NULL;

